import Icon from 'flarum/common/components/Icon';
import classList from 'flarum/common/utils/classList';
import { now, span, statusOf, t, when } from '../api';

/** LIVE (with a pulse), "Starts in 2h 05m" or Finished. */
export function StatusPill() {
  return {
    view: ({
      attrs
    }) => {
      const status = statusOf(attrs.game);
      return m("span", {
        className: classList('BingoStatus', `BingoStatus--${status}`)
      }, status === 'live' && m("span", {
        className: "BingoStatus-dot",
        "aria-hidden": "true"
      }), t(`status.${status}`));
    }
  };
}

/** The line under a game's title: when it starts, how long is left, or when it ended. */
export function clockText(game, coarse = false) {
  const status = statusOf(game);
  if (status === 'upcoming') return t('clock.starts_in', {
    time: span(Date.parse(game.startsAt) - now(), coarse)
  });
  if (status === 'live') return t('clock.ends_in', {
    time: span(Date.parse(game.endsAt) - now(), coarse)
  });
  return t('clock.ended', {
    time: when(game.endsAt)
  });
}
export function Clock() {
  return {
    view: ({
      attrs
    }) => m("span", {
      className: "BingoClock"
    }, m(Icon, {
      name: "far fa-clock"
    }), " ", clockText(attrs.game, attrs.coarse))
  };
}
flarum.reg.add('ernestdefoe-bingo', 'forum/components/parts', { StatusPill: StatusPill,clockText: clockText,Clock: Clock, });