import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import LinkButton from 'flarum/common/components/LinkButton';
import Button from 'flarum/common/components/Button';
import DiscussionControls from 'flarum/forum/utils/DiscussionControls';
import { t } from './api';
import DiscussionBingo from './components/DiscussionBingo';
export { default as extend } from './extend';

/*
 * forum.js is loaded on every page, so it only wires things up: the routes,
 * the sidebar link, the games under a discussion's title, the "Start a
 * Bingo game" control, the event posts and notifications. Pages, the card
 * and the forms are one chunk (play), fetched when first opened.
 */

const page = name => () => import(/* webpackChunkName: 'forum/play', webpackMode: 'lazy-once' */ './play').then(async play => (await play.loadCore(), {
  default: play[name]
}));
app.initializers.add('ernestdefoe/bingo', () => {
  app.routes['bingo'] = {
    path: '/bingo',
    component: page('HubPage')
  };
  app.routes['bingo.game'] = {
    path: '/bingo/:id',
    component: page('GamePage')
  };

  // String form: these components live in lazy chunks, and extending an imported copy patches one core never renders.
  extend('flarum/forum/components/IndexSidebar', 'navItems', function (items) {
    if (!app.forum.attribute('bingoCanView') || !app.forum.attribute('bingoNav')) return;
    items.add('bingo', LinkButton.component({
      href: app.route('bingo'),
      icon: 'fas fa-table-cells'
    }, t('nav')), 79);
  });
  extend('flarum/forum/components/DiscussionHero', 'bodyItems', function (items) {
    const discussion = this.attrs.discussion;
    if ((discussion.attribute('bingoGames') || []).length) {
      items.add('bingo', m(DiscussionBingo, {
        discussion: discussion
      }), 50);
    }
  });
  extend(DiscussionControls, 'userControls', function (items, discussion) {
    if (!discussion.attribute('canStartBingo')) return;
    items.add('bingo', m(Button, {
      icon: "fas fa-table-cells",
      onclick: () => import(/* webpackChunkName: 'forum/play', webpackMode: 'lazy-once' */ './play').then(play => play.openGameForm({
        discussion
      }))
    }, t('controls.start')), -10);
  });
  extend('flarum/forum/components/NotificationGrid', 'notificationTypes', function (items) {
    if (!app.forum.attribute('bingoCanView')) return;
    items.add('bingoReview', {
      name: 'bingoReview',
      icon: 'fas fa-table-cells',
      label: t('notification.review_preference')
    });
    items.add('bingoResult', {
      name: 'bingoResult',
      icon: 'fas fa-trophy',
      label: t('notification.result_preference')
    });
  });
});flarum.reg.addChunkModule('ernestdefoe-bingo:forum/play', '780', 'ernestdefoe-bingo', 'forum/play');
flarum.reg.addChunkModule('ernestdefoe-bingo:forum/play', '780', 'ernestdefoe-bingo', 'forum/components/GameModal');
flarum.reg.addChunkModule('ernestdefoe-bingo:forum/play', '780', 'ernestdefoe-bingo', 'forum/components/HubPage');
flarum.reg.addChunkModule('ernestdefoe-bingo:forum/play', '780', 'ernestdefoe-bingo', 'forum/components/GamePage');
flarum.reg.addChunkModule('ernestdefoe-bingo:forum/play', '780', 'ernestdefoe-bingo', 'forum/components/CardModal');
flarum.reg.addChunkModule('ernestdefoe-bingo:forum/play', '780', 'ernestdefoe-bingo', 'forum/state');
flarum.reg.addChunkModule('ernestdefoe-bingo:forum/play', '780', 'ernestdefoe-bingo', 'forum/components/Panels');
flarum.reg.addChunkModule('ernestdefoe-bingo:forum/play', '780', 'ernestdefoe-bingo', 'forum/components/Card');
flarum.reg.addChunkModule('ernestdefoe-bingo:forum/play', '780', 'ernestdefoe-bingo', 'forum/confetti');