import app from 'flarum/forum/app';
import EventPost from 'flarum/forum/components/EventPost';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import { MEDALS, lineName, placeName, t } from '../api';

/**
 * Bingo in the watch-along thread: a game starting, a call (its standing
 * is updated on the server when it is ruled on) and the results. All it
 * shows is in the post's own content: no request per post.
 */
export default class BingoPost extends EventPost {
  icon() {
    return 'fas fa-table-cells';
  }
  description(data) {
    const c = this.attrs.post.content() || {};
    const href = app.route('bingo.game', {
      id: String(c.game)
    });
    const game = m(Link, {
      className: "BingoPost-game",
      href: href
    }, c.title);
    if (c.kind === 'call') {
      return m("span", null, t('post.called', {
        username: data.username,
        line: lineName(c.line),
        game
      }), ' ', m("span", {
        className: `BingoChip BingoChip--${c.status}`
      }, c.status === 'accepted' ? c.place ? [MEDALS[c.place - 1], ' ', placeName(c.place)] : t('calls.accepted') : c.status === 'rejected' ? t('calls.rejected') : t('calls.pending')), Array.isArray(c.labels) && m("span", {
        className: "BingoPost-labels"
      }, c.labels.join(' · ')));
    }
    if (c.kind === 'results') {
      // Kept true in place: a freed place reopens the game, and calls still being checked are said so.
      if (c.open) return m("span", null, t('post.reopened', {
        game
      }));
      const winners = Array.isArray(c.winners) ? c.winners : [];
      return m("span", null, t('post.results', {
        game
      }), ' ', winners.length ? m("span", {
        className: "BingoPost-winners"
      }, winners.map(([place,, name]) => m("span", {
        className: "BingoPost-winner"
      }, MEDALS[place - 1], " ", name))) : t('post.no_winner'), c.pending > 0 && m("span", {
        className: "BingoPost-labels"
      }, t('post.pending', {
        count: c.pending
      })));
    }
    return m("span", null, t('post.started', {
      username: data.username,
      game,
      count: c.squares || 0
    }), ' ', m(Link, {
      className: "Button Button--primary Button--small BingoPost-play",
      href: href
    }, m(Icon, {
      name: "fas fa-table-cells"
    }), " ", t('post.play')));
  }
}
flarum.reg.add('ernestdefoe-bingo', 'forum/components/BingoPost', BingoPost);